def solve(N):
    if N == 1:
        return "A"

    f = {}
    # f[n] will be True if the player who just wrote n is in a winning position
    # A player is in a winning position if they can move to a position where the next player is in a losing position
    # A player is in a losing position if they can't move to any position where the next player is in a losing position
    # The player who writes N wins, so any n such that n+1=N or 2n=N is a losing position for the player who wrote n.

    for n in range(N, 0, -1):
        if n == N:
            # This is the state after N is written. The player who wrote N has already won.
            # We don't really need f[N] for the logic, but for completeness:
            f[n] = True
        elif n + 1 == N or 2 * n == N:
            f[n] = False
        else:
            # Possible moves from n are n+1 and 2n
            # A player who just wrote n wins if they can move to a position n' such that f[n'] is False
            can_move_to_loss = False

            # Move to n+1
            if n + 1 < N:
                if f[n+1] == False:
                    can_move_to_loss = True

            # Move to 2n
            if 2 * n < N:
                if f[2 * n] == False:
                    can_move_to_loss = True

            if can_move_to_loss:
                f[n] = True
            else:
                f[n] = False

    return "A" if f[1] == True else "B"

