def solve_correct(N):
    if N == 1:
        return "A"

    W = {}
    for n in range(N, 0, -1):
        if n == N:
            # The player who just wrote N has already won.
            # This state is not reachable for the player who is about to move.
            continue

        # Can the player who is about to move win?
        can_win = False
        # Option 1: Can they write N directly?
        if n + 1 == N or 2 * n == N:
            can_win = True
        else:
            # Option 2: Can they move to a position n' where the next player loses?
            # Moves from n are n+1 and 2n
            moves = []
            if n + 1 <= N:
                moves.append(n + 1)
            if 2 * n <= N:
                moves.append(2 * n)

            for m in moves:
                if m == N:
                    # This move wins immediately
                    can_win = True
                    break
                if W[m] == False:
                    can_win = True
                    break

        W[n] = can_win

    # A writes 1, so we want to know if the player about to move (B) wins.
    # If W[1] is False, then B loses, so A wins (Type A).
    # If W[1] is True, then B wins (Type B).
    return "A" if W[1] == False else "B"

