def is_type_B(N):
    # f(n) = W if player whose turn it is to move from n can win
    # f(n) = L if player whose turn it is to move from n loses
    # f(n) = W if n+1 = N or 2n = N or (n+1 < N and f(n+1) = L) or (2n < N and f(2n) = L)
    f = {}
    for n in range(N - 1, 0, -1):
        can_move_to_N = (n + 1 == N) or (2 * n == N)
        if can_move_to_N:
            f[n] = "W"
        else:
            moves = []
            if n + 1 < N:
                moves.append(n + 1)
            if 2 * n < N:
                moves.append(2 * n)

            # f[n] is W if there's a move to an L position
            if any(f[m] == "L" for m in moves):
                f[n] = "W"
            else:
                f[n] = "L"
    return f[1] == "W"

